"""Build one isolated native DFMA cup; retain the published baseline untouched."""
import json
from pathlib import Path
from run_native import rpc
from fetch_exports import fetch
ROOT=Path(__file__).resolve().parents[1]
script='\n'.join((ROOT/'source'/p).read_text()for p in ['native_documents.py','intent_geometry.py','cohesive_limb_intent.py','paired_roll_intent.py','cohesive_crank_intent.py','cohesive_carrier_intent.py','paired_cup_intent.py','dfma_rear_loaded_cup_intent.py'])+'''
def run(_context:str):
 import json,os,time,hashlib
 app=core.Application.get();doc=authoring_document(app,'leg');assert doc.dataFile.versionNumber==30 and doc.dataFile.isComplete and not doc.isModified;doc.activate();d=fusion.Design.cast(app.activeProduct);assert d.activateRootComponent();root=d.rootComponent;tick=time.monotonic();baseline={p.name:p.expression for p in d.userParameters};visibility=[{'part_number':o.component.partNumber,'visible':o.isLightBulbOn}for o in root.occurrences];assert not any(c.partNumber=='DFMA_PROPOSAL_FL'for c in d.allComponents)
 folder=os.path.join(os.path.expanduser('~'),'Library','Caches','Tinfox','dfma-architecture-v1');os.makedirs(folder,exist_ok=True);journal=os.path.join(folder,'native-build-progress.json')
 def progress(stage):open(journal,'w').write(json.dumps({'stage':stage,'saved_baseline_leg_version':30,'elapsed_seconds':time.monotonic()-tick}))
 progress('create isolated proposal');group=root.occurrences.addNewComponent(core.Matrix3D.create());group.component.name='DFMA one-leg architecture proposal';group.component.partNumber='DFMA_PROPOSAL_FL';group.component.attributes.add('Tinfox','Status','Unqualified architecture proposal. Master63 and Leg30 baseline are preserved.');occ=group.component.occurrences.addNewComponent(core.Matrix3D.create());c=occ.component;c.name='Rear-loaded integral hip cup';c.partNumber='DFMA_REAR_LOADED_CUP_FL';progress('author native revolutions, fan, mounting patterns');builder=DfmaRearLoadedCupIntent(IntentGeometry(d,c));body=builder.cup();assert c.bRepBodies.count==1 and body.isSolid;assert all(f.healthState==fusion.FeatureHealthStates.HealthyFeatureHealthState for f in c.features);body.name='Integral rear-loaded motor cup and journal';parent=[v for v in d.allComponents if v.partNumber=='CANDIDATE_rc_motor_carrier_1'];assert len(parent)==1;body.appearance=parent[0].bRepBodies.item(0).appearance;c.attributes.add('Tinfox','ManufacturingStatus','DFMA architecture candidate. Rear motor insertion, straight driver paths, retained journal sections and manufacturing access require focused checks. No strength release.');c.attributes.add('Tinfox','PartsRemoved','Separate hip stator closure, three M4 closure screws and three nuts. All nine stator holes and six output holes retained.');assert all(d.userParameters.itemByName(k).expression==v for k,v in baseline.items());progress('export changed native part')
 for o in root.occurrences:o.isLightBulbOn=o.component.partNumber=='DFMA_PROPOSAL_FL'
 for sk in c.sketches:sk.isVisible=False
 for plane in c.constructionPlanes:plane.isLightBulbOn=False
 path=os.path.join(folder,'dfma-rear-loaded-cup.step');assert d.exportManager.execute(d.exportManager.createSTEPExportOptions(path,c));assert os.path.getsize(path)>5000;camera=app.activeViewport.camera;camera.eye=core.Point3D.create(18,-22,17);camera.target=core.Point3D.create(-2,-2,0);camera.upVector=core.Vector3D.create(0,0,1);camera.isSmoothTransition=False;app.activeViewport.camera=camera;app.activeViewport.fit();app.activeViewport.refresh();png=os.path.join(folder,'dfma-rear-loaded-cup.png');assert app.activeViewport.saveAsImageFile(png,1400,1000);bb=body.boundingBox;progress('native cup built and exported; focused checks pending');print(json.dumps({'built':True,'saved':False,'saved_baseline_leg_version':30,'part_number':c.partNumber,'features':c.features.count,'sketches':c.sketches.count,'faces':body.faces.count,'edges':body.edges.count,'solid_bodies':c.bRepBodies.count,'bounds_mm':[x*10 for x in [*bb.minPoint.asArray(),*bb.maxPoint.asArray()]],'paths':[{'path':p,'sha256':hashlib.sha256(open(p,'rb').read()).hexdigest()}for p in [path,png]],'baseline_parameter_expressions_unchanged':True,'previous_root_visibility':visibility,'new_parameters':[p.name for p in d.userParameters if p.name not in baseline],'elapsed_seconds':time.monotonic()-tick,'scope':'One new native component in an isolated proposal group. No baseline definition, assembly transform or published Master reference was edited.'}))
'''
r=rpc(script,'dfma-rear-loaded-cup-native',timeout=1200);assert r[0]['success'],r;record=json.loads(r[0]['message']);(ROOT/'audits/dfma-rear-loaded-cup-native.json').write_text(json.dumps(record,indent=2));print({k:v for k,v in record.items()if k!='previous_root_visibility'},flush=True)
for row in record['paths']:fetch(row['path'],'dfma-architecture-v1/'+Path(row['path']).name)
